import { bindSetIcon, renderSetIcon } from "../icon-set-core.js";

export const definition = {
  "name": "messages",
  "category": "Communication",
  "viewBox": "0 0 24 24",
  "mode": "stroke",
  "strokeWidth": 2,
  "motion": "chat",
  "parts": [
    {
      "tag": "path",
